`timescale 1ns/1ps
// Auto-generated by autombist from config.yml: a BEHAVIORAL model of the memory,
// writes on the rising edge, reads one clock after the registered access, data held until the next read (read_latency 1).
// Idealized: fault-free, no timing checks, contents power up unknown. It is NOT the
// macro's own model; pass that model to run_tb.sh to replace this one.
module sram_tcol #(
    parameter integer ADDR_WIDTH = 4,
    parameter integer DATA_WIDTH = 8,
    parameter integer NUM_SPARE_ROWS = 1,
    parameter integer NUM_SPARE_COLS = 1
) (
    input  wire clk0,
    input  wire csb0,
    input  wire web0,
    input  wire [4:0] addr0,
    input  wire [8:0] din0,
    input  wire [0:0] spare_wen0,
    output reg  [8:0] dout0
);
    // The wrapper overrides the parameters above; the widths below are the ones it connects.
    localparam integer LOGICAL_W = 8;
    localparam integer DEPTH = 32;
    reg [8:0] mem [0:DEPTH-1];

    // port 0: rw
    reg p0_csb_q;
    reg [4:0] p0_addr_q;
    reg p0_we_q;
    integer p0_k;
    always @(posedge clk0) begin
        p0_csb_q  <= csb0;
        p0_addr_q <= addr0;
        p0_we_q   <= web0;
        if (!csb0 && !web0) begin
            mem[addr0][LOGICAL_W-1:0] <= din0[LOGICAL_W-1:0];
            for (p0_k = 0; p0_k < 1; p0_k = p0_k + 1)
                if (spare_wen0[p0_k]) mem[addr0][LOGICAL_W + p0_k] <= din0[LOGICAL_W + p0_k];
        end
        if (!p0_csb_q && p0_we_q) dout0 <= mem[p0_addr_q];
    end

endmodule
